create or replace function public.platform_create_new_owner_invitation(p_conference_name text,p_owner_name text,p_email text)
returns uuid language plpgsql security definer set search_path='' as $$ declare v_owner_id uuid;v_token uuid;begin if not public.is_platform_creator() then raise exception 'Platform Creator access is required.';end if;if char_length(trim(p_conference_name)) not between 2 and 80 or char_length(trim(p_owner_name)) not between 2 and 100 or position('@' in trim(p_email))=0 then raise exception 'Enter the conference name, owner name, and email.';end if;insert into public.platform_owner_records(full_name,email) values(trim(p_owner_name),lower(trim(p_email))) returning id into v_owner_id;insert into public.platform_owner_invitations(conference_name,email,invited_by,owner_record_id) values(trim(p_conference_name),lower(trim(p_email)),(select auth.uid()),v_owner_id) returning token into v_token;return v_token;end;$$;
revoke all on function public.platform_create_new_owner_invitation(text,text,text) from public;
grant execute on function public.platform_create_new_owner_invitation(text,text,text) to authenticated;
